const SLOGANS = [
  "Generating FOMO...",
  "Convincing the bears to hibernate...",
  "Drawing arbitrary lines on charts...",
  "Looking for the seed phrase...",
  "Calculating Wen Lambo...",
  "Mining fiat to buy the dip...",
  "Re-calibrating the diamond hands...",
  "Polishing the moon boots...",
  "Syncing with the simulation...",
  "Deleting leverage..."
];

export const SplashScreen: React.FC<{ onFinish: () => void }> = ({ onFinish }) => {
  const [progress, setProgress] = useState(0);
  const [sloganIndex, setSloganIndex] = useState(0);

  useEffect(() => {
    // Progress Timer - Fills in about 2.5 seconds
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(onFinish, 600); // Slight delay after 100% before unmounting
          return 100;
        }
        // Randomize increment for realism
        return prev + Math.random() * 8;
      });
    }, 150);

    return () => clearInterval(interval);
  }, [onFinish]);

  useEffect(() => {
    // Slogan Rotator
    const interval = setInterval(() => {
      setSloganIndex(prev => (prev + 1) % SLOGANS.length);
    }, 1200); // Change slogan every 1.2s

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 z-[9999] bg-[#050507] flex flex-col items-center justify-center relative overflow-hidden select-none">
      {/* Background Ambience */}
      <div className="absolute inset-0 bg-gradient-to-br from-emerald-900/10 via-transparent to-purple-900/10 pointer-events-none"></div>

      {/* Content */}
      <div className="relative z-10 flex flex-col items-center gap-10 max-w-md w-full px-6">

        {/* Logo Section */}
        <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in duration-700">
           <Logo />
           <h1 className="text-5xl font-black text-white tracking-[0.2em] uppercase drop-shadow-[0_0_10px_rgba(255,255,255,0.3)]">Cryptix</h1>
        </div>

        {/* Progress Section */}
        <div className="w-full max-w-xs flex flex-col items-center gap-4">
           {/* Bar */}
           <div className="w-full h-1 bg-zinc-900 rounded-full overflow-hidden border border-white/5 relative">
              <div 
                className="h-full bg-gradient-to-r from-emerald-500 via-emerald-400 to-purple-500 shadow-[0_0_15px_rgba(16,185,129,0.8)] transition-all duration-200 ease-out relative" 
                style={{ width: `${progress}%` }}
              >
                  {/* Leading glow */}
                  <div className="absolute right-0 top-0 bottom-0 w-2 bg-white blur-[2px]"></div>
              </div>
           </div>

           {/* Percentage */}
           <span className="text-[10px] font-mono text-zinc-600 font-bold">{Math.floor(progress)}%</span>
        </div>

        {/* Slogan */}
        <div className="h-8 flex items-center justify-center">
           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em] animate-pulse text-center">
              {SLOGANS[sloganIndex]}
           </p>
        </div>

      </div>
    </div>
  );
};

