            <div className="max-w-[1700px] mx-auto animate-in fade-in slide-in-from-bottom-2 duration-500 w-full">
              <ExecutionView initialState={tradeConfig} />
            </div>
          </div>
        );
      case 'pro-trade':
        return (
          <div className="h-full w-full p-2 overflow-hidden">
            <ProTradingView />
          </div>
        );
      case 'history':
