// --- SANITY CHECK MODAL COMPONENT ---
interface SanityCheckProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  leverage: number;
  side: 'buy' | 'sell';
  liqPrice: string;
  distance: string;
}

const SanityCheckModal: React.FC<SanityCheckProps> = ({ isOpen, onClose, onConfirm, leverage, side, liqPrice, distance }) => {
  const [timer, setTimer] = useState(5);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isOpen) {
      setTimer(5);
      interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/90 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-[#09090b] border border-rose-500/50 rounded-2xl w-full max-w-md shadow-[0_0_100px_-20px_rgba(244,63,94,0.5)] overflow-hidden transform animate-in zoom-in-95 duration-200 relative">

        {/* Header */}
        <div className="bg-rose-500/10 p-6 border-b border-rose-500/20 flex items-center gap-4">
           <div className="p-3 bg-rose-500/20 rounded-full border border-rose-500/50 text-rose-500 animate-pulse">
              <Skull size={24} />
           </div>
           <div>
              <h2 className="text-xl font-black text-white uppercase tracking-tight">High Leverage Warning</h2>
              <p className="text-rose-400 text-xs font-bold uppercase tracking-widest">{leverage}x Leverage Selected</p>
           </div>
        </div>

        {/* Body */}
        <div className="p-6 space-y-6">
           <div className="space-y-4 text-sm text-zinc-300 leading-relaxed">
              <p>
                You are about to open a <strong>{leverage}x {side.toUpperCase()}</strong> position. 
                This is considered <span className="text-white font-bold underline decoration-rose-500">extremely high risk</span>.
              </p>

              <div className="bg-rose-950/30 border border-rose-500/20 p-4 rounded-xl space-y-2">
                 <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-zinc-400 uppercase tracking-wider">Liquidation Price</span>
                    <span className="text-lg font-mono font-bold text-rose-500">{liqPrice}</span>
                 </div>
                 <div className="h-px bg-rose-500/20 w-full"></div>
                 <p className="text-xs font-medium text-rose-300">
                    A move of just <span className="font-black text-white bg-rose-500 px-1 rounded mx-1">{distance}%</span> against you will result in <span className="font-black">TOTAL LOSS</span> of funds.
                 </p>
              </div>
           </div>

           <div className="flex items-center gap-3">
              <button 
                onClick={onClose}
                className="flex-1 py-4 rounded-xl font-bold text-xs uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-zinc-400 hover:text-white transition-colors"
              >
                Cancel Trade
              </button>
              <button 
                onClick={onConfirm}
                disabled={timer > 0}
                className={`flex-1 py-4 rounded-xl font-black text-xs uppercase tracking-widest transition-all shadow-lg flex items-center justify-center gap-2 ${
                    timer > 0 
                    ? 'bg-zinc-900 border border-zinc-800 text-zinc-600 cursor-not-allowed' 
                    : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/50'
                }`}
              >
                {timer > 0 ? (
                    <>
                        <Timer size={14} className="animate-spin" /> 
                        Wait {timer}s
                    </>
                ) : (
                    <>
                        <AlertOctagon size={14} /> 
                        I Understand the Risk
                    </>
                )}
              </button>
           </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

