// --- SANITY CHECK MODAL ---
interface SanityCheckProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  leverage: number;
  side: 'long' | 'short';
  liqPrice: string;
  distance: string;
}

const SanityCheckModal: React.FC<SanityCheckProps> = ({ isOpen, onClose, onConfirm, leverage, side, liqPrice, distance }) => {
  const [timer, setTimer] = useState(3);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isOpen) {
      setTimer(3);
      interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-[#09090b] border border-rose-500/30 rounded-3xl w-full max-w-sm shadow-[0_0_50px_-10px_rgba(244,63,94,0.3)] overflow-hidden transform animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-rose-500/10 p-5 border-b border-rose-500/20 flex items-center gap-4">
           <div className="p-2.5 bg-rose-500/20 rounded-full text-rose-500 animate-pulse">
              <Skull size={20} />
           </div>
           <div>
              <h2 className="text-base font-black text-white uppercase tracking-wide">High Risk Warning</h2>
              <p className="text-rose-400 text-[10px] font-bold uppercase tracking-widest">{leverage}x Leverage</p>
           </div>
        </div>

        {/* Body */}
        <div className="p-6 space-y-5">
           <p className="text-xs text-zinc-300 font-medium leading-relaxed">
             You are opening a <span className={side === 'long' ? 'text-emerald-500 font-bold' : 'text-rose-500 font-bold'}>{side.toUpperCase()}</span> position. 
             Price movement of <span className="text-white font-bold bg-rose-500/20 px-1 rounded">{distance}%</span> against you triggers liquidation.
           </p>

           <div className="bg-black/40 border border-white/5 rounded-xl p-3 flex justify-between items-center">
              <span className="text-[10px] font-bold text-zinc-500 uppercase">Liq. Price</span>
              <span className="text-sm font-mono font-bold text-rose-500">{liqPrice}</span>
           </div>

           <div className="flex gap-3 pt-2">
              <button 
                onClick={onClose}
                className="flex-1 py-3 rounded-xl font-bold text-[10px] uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-zinc-400 hover:text-white transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={onConfirm}
                disabled={timer > 0}
                className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-lg flex items-center justify-center gap-2 ${
                    timer > 0 
                    ? 'bg-zinc-900 border border-zinc-800 text-zinc-600 cursor-not-allowed' 
                    : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/50'
                }`}
              >
                {timer > 0 ? `Wait ${timer}s` : 'Confirm'}
              </button>
           </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

