import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  ChevronDown, 
  Maximize2, 
  Settings2, 
  Lock, 
  Unlock, 
  Crosshair, 
  PenTool, 
  Hash, 
  Globe, 
  Skull, 
  Minus, 
  Plus, 
  Wallet,
  TrendingUp,
  AlertTriangle,
  RefreshCw
} from 'lucide-react';
import { createPortal } from 'react-dom';

// --- TYPES ---
interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
}

// --- SYNTHETIC CHART GENERATOR (BTC Logic) ---
const generateSyntheticCandles = (count: number, startPrice: number): Candle[] => {
  const candles: Candle[] = [];
  let currentPrice = startPrice;
  const now = Date.now();
  const timeStep = 15 * 60 * 1000; // 15 min

  for (let i = count; i > 0; i--) {
    const volatility = currentPrice * 0.002; // 0.2% volatility per candle
    const trend = (Math.random() - 0.5) * volatility * 0.5; // Slight drift

    const open = currentPrice;
    const close = open + ((Math.random() - 0.5) * volatility) + trend;

    // Wicks
    const high = Math.max(open, close) + (Math.random() * volatility * 0.8);
    const low = Math.min(open, close) - (Math.random() * volatility * 0.8);

    candles.push({
      time: now - (i * timeStep),
      open,
      high,
      low,
      close
    });

    currentPrice = close;
  }
  return candles;
};

// --- SANITY CHECK MODAL ---
interface SanityCheckProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  leverage: number;
  side: 'long' | 'short';
  liqPrice: number;
  distance: string;
}

const SanityCheckModal: React.FC<SanityCheckProps> = ({ isOpen, onClose, onConfirm, leverage, side, liqPrice, distance }) => {
  const [timer, setTimer] = useState(3);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isOpen) {
      setTimer(3);
      interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-[#09090b] border border-rose-500/30 rounded-3xl w-full max-w-sm shadow-[0_0_50px_-10px_rgba(244,63,94,0.3)] overflow-hidden transform animate-in zoom-in-95 duration-200">
        <div className="bg-rose-500/10 p-5 border-b border-rose-500/20 flex items-center gap-4">
           <div className="p-2.5 bg-rose-500/20 rounded-full text-rose-500 animate-pulse">
              <Skull size={20} />
           </div>
           <div>
              <h2 className="text-base font-black text-white uppercase tracking-wide">High Leverage Alert</h2>
              <p className="text-rose-400 text-[10px] font-bold uppercase tracking-widest">{leverage}x Leverage</p>
           </div>
        </div>
        <div className="p-6 space-y-5">
           <p className="text-xs text-zinc-300 font-medium leading-relaxed">
             You are opening a <span className={side === 'long' ? 'text-emerald-500 font-bold' : 'text-rose-500 font-bold'}>{side.toUpperCase()}</span> position. 
             Price movement of <span className="text-white font-bold bg-rose-500/20 px-1 rounded">{distance}%</span> against you triggers immediate liquidation.
           </p>
           <div className="bg-black/40 border border-white/5 rounded-xl p-3 flex justify-between items-center">
              <span className="text-[10px] font-bold text-zinc-500 uppercase">Liq. Price</span>
              <span className="text-sm font-mono font-bold text-rose-500">${liqPrice.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span>
           </div>
           <div className="flex gap-3 pt-2">
              <button onClick={onClose} className="flex-1 py-3 rounded-xl font-bold text-[10px] uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-zinc-400 hover:text-white transition-colors">Cancel</button>
              <button onClick={onConfirm} disabled={timer > 0} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${timer > 0 ? 'bg-zinc-900 border border-zinc-800 text-zinc-600 cursor-not-allowed' : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/50'}`}>
                {timer > 0 ? `Wait ${timer}s` : 'Confirm'}
              </button>
           </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

const ProTradingView: React.FC = () => {
  // --- STATE ---
  const [side, setSide] = useState<'long' | 'short'>('long'); 
  const [orderType, setOrderType] = useState<'limit' | 'market'>('market');

  // Market Data (Synthetic)
  const [currentPrice, setCurrentPrice] = useState(64250.00); // BTC-ish Price
  const [candles, setCandles] = useState<Candle[]>([]);

  // Inputs
  const [priceInput, setPriceInput] = useState('');
  const [collateralInput, setCollateralInput] = useState('');
  const [leverage, setLeverage] = useState(20);
  const [isDegenMode, setIsDegenMode] = useState(false);

  // Risk Management
  const [tpEnabled, setTpEnabled] = useState(false);
  const [slEnabled, setSlEnabled] = useState(false);
  const [tpPercent, setTpPercent] = useState('50'); // Target ROI %
  const [slPercent, setSlPercent] = useState('20'); // Stop Loss ROI %

  // UI
  const [showSanityCheck, setShowSanityCheck] = useState(false);

  // Initialize Chart
  useEffect(() => {
    const data = generateSyntheticCandles(60, 64250.00);
    setCandles(data);
    setCurrentPrice(data[data.length - 1].close);
  }, []);

  // Live Price Ticker Simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setCurrentPrice(prev => prev + (Math.random() - 0.5) * 15);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // --- PRECISE MATH ENGINE ---
  const entryPrice = orderType === 'market' ? currentPrice : parseFloat(priceInput) || currentPrice;
  const collateral = parseFloat(collateralInput) || 0;
  const positionSize = collateral * leverage;

  // Liquidation: 
  // Long: Entry * (1 - 1/Lev)
  // Short: Entry * (1 + 1/Lev)
  const liqPrice = useMemo(() => {
      if (side === 'long') return entryPrice * (1 - (1/leverage));
      else return entryPrice * (1 + (1/leverage));
  }, [entryPrice, leverage, side]);

  // Take Profit Price (Targeting ROE %)
  // Long: Entry * (1 + (Target% / 100 / Leverage))
  const tpPrice = useMemo(() => {
      const targetPct = parseFloat(tpPercent) || 0;
      if (side === 'long') return entryPrice * (1 + (targetPct / 100) / leverage);
      else return entryPrice * (1 - (targetPct / 100) / leverage);
  }, [entryPrice, tpPercent, leverage, side]);

  // Stop Loss Price (Targeting Loss %)
  const slPrice = useMemo(() => {
      const targetPct = parseFloat(slPercent) || 0;
      if (side === 'long') return entryPrice * (1 - (targetPct / 100) / leverage);
      else return entryPrice * (1 + (targetPct / 100) / leverage);
  }, [entryPrice, slPercent, leverage, side]);

  const distanceToLiq = Math.abs(((entryPrice - liqPrice) / entryPrice) * 100).toFixed(2);
  const fees = positionSize * 0.0006; // 0.06% Taker

  // --- CHART SCALING ---
  // Determine Y-Axis domain to fit candles AND active lines
  const chartMin = useMemo(() => {
      let min = Math.min(...candles.map(c => c.low));
      if (tpEnabled) min = Math.min(min, tpPrice);
      if (slEnabled) min = Math.min(min, slPrice);
      min = Math.min(min, liqPrice);
      return min * 0.995; // 0.5% padding
  }, [candles, tpEnabled, slEnabled, tpPrice, slPrice, liqPrice]);

  const chartMax = useMemo(() => {
      let max = Math.max(...candles.map(c => c.high));
      if (tpEnabled) max = Math.max(max, tpPrice);
      if (slEnabled) max = Math.max(max, slPrice);
      max = Math.max(max, liqPrice);
      return max * 1.005; // 0.5% padding
