  const [isDegenMode, setIsDegenMode] = useState(false);

  // Risk Management
  const [tpslEnabled, setTpslEnabled] = useState(false);

  // We store the percentages as the source of truth, but allow inputs to override temporarily
  const [tpPercent, setTpPercent] = useState('50'); // Target ROI %
  const [slPercent, setSlPercent] = useState('20'); // Stop Loss ROI %

  // UI
  const [showSanityCheck, setShowSanityCheck] = useState(false);

  // Initialize Chart
  useEffect(() => {
    const data = generateSyntheticCandles(60, 64250.00);
    setCandles(data);
    setCurrentPrice(data[data.length - 1].close);
  }, []);

  // Live Price Ticker Simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setCurrentPrice(prev => prev + (Math.random() - 0.5) * 15);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // --- PRECISE MATH ENGINE ---
  const entryPrice = orderType === 'market' ? currentPrice : parseFloat(priceInput) || currentPrice;
  const collateral = parseFloat(collateralInput) || 0;
  const positionSize = collateral * leverage;

  // Liquidation: 
  // Long: Entry * (1 - 1/Lev)
  // Short: Entry * (1 + 1/Lev)
  const liqPrice = useMemo(() => {
      if (side === 'long') return entryPrice * (1 - (1/leverage));
      else return entryPrice * (1 + (1/leverage));
  }, [entryPrice, leverage, side]);

  // Take Profit Price (Targeting ROE %)
  // Long: Entry * (1 + (Target% / 100 / Leverage))
  const tpPrice = useMemo(() => {
      const targetPct = parseFloat(tpPercent) || 0;
      if (side === 'long') return entryPrice * (1 + (targetPct / 100) / leverage);
      else return entryPrice * (1 - (targetPct / 100) / leverage);
  }, [entryPrice, tpPercent, leverage, side]);

  // Stop Loss Price (Targeting Loss %)
  const slPrice = useMemo(() => {
      const targetPct = parseFloat(slPercent) || 0;
      if (side === 'long') return entryPrice * (1 - (targetPct / 100) / leverage);
      else return entryPrice * (1 + (targetPct / 100) / leverage);
  }, [entryPrice, slPercent, leverage, side]);

  // Reverse Calculations for Inputs
  const handleTpPriceInput = (val: string) => {
      const price = parseFloat(val);
      if (!price) return;

      let newPct = 0;
      if (side === 'long') {
          // ROI = (Price / Entry - 1) * Leverage * 100
          newPct = ((price / entryPrice) - 1) * leverage * 100;
      } else {
          // ROI = (1 - Price / Entry) * Leverage * 100
          newPct = (1 - (price / entryPrice)) * leverage * 100;
      }
      setTpPercent(newPct.toFixed(2));
  };

  const handleSlPriceInput = (val: string) => {
      const price = parseFloat(val);
      if (!price) return;

      let newPct = 0;
      if (side === 'long') {
          // Loss % = (1 - Price / Entry) * Leverage * 100 (Represented as positive number for input)
          newPct = (1 - (price / entryPrice)) * leverage * 100;
      } else {
          // Loss % = (Price / Entry - 1) * Leverage * 100
          newPct = ((price / entryPrice) - 1) * leverage * 100;
      }
      setSlPercent(newPct.toFixed(2));
  };

  const distanceToLiq = Math.abs(((entryPrice - liqPrice) / entryPrice) * 100).toFixed(2);
  const fees = positionSize * 0.0006; // 0.06% Taker

  // --- CHART SCALING ---
  const chartMin = useMemo(() => {
      let min = Math.min(...candles.map(c => c.low));
      if (tpslEnabled) {
          min = Math.min(min, tpPrice, slPrice);
      }
      min = Math.min(min, liqPrice);
      return min * 0.995; 
  }, [candles, tpslEnabled, tpPrice, slPrice, liqPrice]);

  const chartMax = useMemo(() => {
      let max = Math.max(...candles.map(c => c.high));
      if (tpslEnabled) {
          max = Math.max(max, tpPrice, slPrice);
      }
      max = Math.max(max, liqPrice);
      return max * 1.005; 
  }, [candles, tpslEnabled, tpPrice, slPrice, liqPrice]);

  const getY = (price: number) => {
      return ((price - chartMin) / (chartMax - chartMin)) * 100;
  };

  const handleExecute = () => {
      if (leverage > 20) setShowSanityCheck(true);
      else console.log("Execute");
  };

  // Theme Colors based on Side
  const themeBg = side === 'long' ? 'bg-emerald-500' : 'bg-rose-500';

