            </span>
            <button className="flex items-center space-x-2 text-white hover:text-emerald-500 transition-colors group">
              <span className="text-[13px] font-black tracking-tight">BTC-USDT</span>
              <ChevronDown size={14} className="text-zinc-600 group-hover:text-white" />
            </button>
          </div>
        </div>
        {[
          { label: 'Mark Price', val: currentPrice.toLocaleString('en-US', {maximumFractionDigits: 2}), color: 'text-white' },
