          { label: 'Funding', val: '0.001%', sub: '00:42:12', color: 'text-amber-500' },
          { label: '24h Change', val: '+2.45%', color: 'text-emerald-500' },
          { label: '24h Volume', val: '42B', color: 'text-zinc-300' },
          { label: 'Open Interest', val: '12B', color: 'text-zinc-300' },
          { label: 'Trades', val: '152/s', color: 'text-purple-400' },
        ].map((stat, i) => (
          <div key={i} className="bg-[#0a0a0a] p-2 border-r border-zinc-800 flex flex-col justify-center">
