  const [isDegenMode, setIsDegenMode] = useState(false);

  // Risk Management
  const [tpslEnabled, setTpslEnabled] = useState(false);

  // Percentages are the source of truth for calculations
  const [tpPercent, setTpPercent] = useState('50'); // Target ROI %
  const [slPercent, setSlPercent] = useState('20'); // Stop Loss ROI %

  // UI
  const [showSanityCheck, setShowSanityCheck] = useState(false);

  // Initialize Chart
  useEffect(() => {
    const data = generateSyntheticCandles(60, 64250.00);
    setCandles(data);
    setCurrentPrice(data[data.length - 1].close);
  }, []);

  // Live Price Ticker Simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setCurrentPrice(prev => prev + (Math.random() - 0.5) * 15);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // --- PRECISE MATH ENGINE ---
  const entryPrice = orderType === 'market' ? currentPrice : parseFloat(priceInput) || currentPrice;
  const collateral = parseFloat(collateralInput) || 0;
  const positionSize = collateral * leverage;

  // Max Leverage based on Degen Mode
