  // Liquidation: 
  // Long: Entry * (1 - 1/Lev)
  // Short: Entry * (1 + 1/Lev)
  const liqPrice = useMemo(() => {
      if (side === 'long') return entryPrice * (1 - (1/leverage));
      else return entryPrice * (1 + (1/leverage));
