  // Market Data (Synthetic)
  const [currentPrice, setCurrentPrice] = useState(64250.00); // BTC-ish Price
  const [candles, setCandles] = useState<Candle[]>([]);

  // Inputs
  const [priceInput, setPriceInput] = useState('');
  const [collateralInput, setCollateralInput] = useState('');
  const [leverage, setLeverage] = useState(20);
  const [isDegenMode, setIsDegenMode] = useState(false);

  // Risk Management
  const [tpslEnabled, setTpslEnabled] = useState(false);

  // Percentages are the source of truth for calculations
  const [tpPercent, setTpPercent] = useState('50'); // Target ROI %
  const [slPercent, setSlPercent] = useState('20'); // Stop Loss ROI %

  // UI
  const [showSanityCheck, setShowSanityCheck] = useState(false);

  // Initialize Chart
  useEffect(() => {
    const data = generateSyntheticCandles(60, 64250.00);
    setCandles(data);
    setCurrentPrice(data[data.length - 1].close);
  }, []);

  // Live Price Ticker Simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setCurrentPrice(prev => prev + (Math.random() - 0.5) * 15);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // --- PRECISE MATH ENGINE ---
  const entryPrice = orderType === 'market' ? currentPrice : parseFloat(priceInput) || currentPrice;
  const collateral = parseFloat(collateralInput) || 0;
  const positionSize = collateral * leverage;

  // Max Leverage based on Degen Mode
  // Standard: 100x | Degen: 1000x
  const maxLeverage = isDegenMode ? 1000 : 100;

  // Liquidation: 
  // Long: Entry * (1 - 1/Lev)
  // Short: Entry * (1 + 1/Lev)
  const liqPrice = useMemo(() => {
      if (side === 'long') return entryPrice * (1 - (1/leverage));
      else return entryPrice * (1 + (1/leverage));
  }, [entryPrice, leverage, side]);

  // Take Profit Price (Targeting ROE %)
  // Long: Entry * (1 + (Target% / 100 / Leverage))
  const tpPrice = useMemo(() => {
      const targetPct = parseFloat(tpPercent) || 0;
      if (side === 'long') return entryPrice * (1 + (targetPct / 100) / leverage);
      else return entryPrice * (1 - (targetPct / 100) / leverage);
  }, [entryPrice, tpPercent, leverage, side]);

  // Stop Loss Price (Targeting Loss %)
  const slPrice = useMemo(() => {
      const targetPct = parseFloat(slPercent) || 0;
      if (side === 'long') return entryPrice * (1 - (targetPct / 100) / leverage);
      else return entryPrice * (1 + (targetPct / 100) / leverage);
  }, [entryPrice, slPercent, leverage, side]);

  // --- BIDIRECTIONAL INPUT HANDLERS ---
  const handleTpPriceInput = (val: string) => {
      // Allow empty string for deleting
      if (val === '') {
          setTpPercent('0');
          return;
      }
      const newPrice = parseFloat(val);
      if (isNaN(newPrice)) return;

      let newPct = 0;
      if (side === 'long') {
          // ROI = (Price / Entry - 1) * Leverage * 100
          newPct = ((newPrice / entryPrice) - 1) * leverage * 100;
      } else {
          // ROI = (1 - Price / Entry) * Leverage * 100
          newPct = (1 - (newPrice / entryPrice)) * leverage * 100;
      }
      // Allow negative ROI while typing (e.g. user sets TP below entry by mistake, we still show it)
      setTpPercent(newPct.toFixed(2));
