            <div className="flex items-baseline gap-1">
                <p className="text-amber-500 font-mono font-bold text-xs">0.004%</p>
                <span className="text-[9px] font-mono text-zinc-600">{fundingTimer}</span>
            </div>
        </div>

        {/* 5. PROTOCOL TRANSPARENCY STATS (NEW) */}
        <div className="bg-[#0a0a0a] p-2 border-r border-zinc-800 flex flex-col justify-center col-span-2 relative group cursor-help">
            <p className="text-[9px] text-zinc-500 font-bold uppercase mb-0.5 tracking-tight flex items-center gap-1">
                <ShieldCheck size={10} className="text-emerald-500" /> Insurance Fund
            </p>
            <p className="text-white font-mono font-bold text-xs">$42.5M <span className="text-emerald-500 text-[9px]">(Solvent)</span></p>
            {/* Tooltip */}
            <div className="absolute top-full left-0 mt-2 w-48 bg-zinc-900 border border-white/10 p-3 rounded-lg shadow-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                <p className="text-[10px] text-zinc-300">All liquidation penalties go here to secure the protocol. 0% goes to the team.</p>
            </div>
        </div>
        <div className="bg-[#0a0a0a] p-2 border-r border-zinc-800 flex flex-col justify-center col-span-2 relative group cursor-help">
            <p className="text-[9px] text-zinc-500 font-bold uppercase mb-0.5 tracking-tight flex items-center gap-1">
                <Coins size={10} className="text-purple-500" /> Rev Distributed
            </p>
            <p className="text-white font-mono font-bold text-xs">$14.2M <span className="text-purple-500 text-[9px]">(Paid)</span></p>
             {/* Tooltip */}
             <div className="absolute top-full right-0 mt-2 w-48 bg-zinc-900 border border-white/10 p-3 rounded-lg shadow-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                <p className="text-[10px] text-zinc-300">100% of trading fees are redistributed to active traders and liquidity providers.</p>
            </div>
        </div>
      </header>

      {/* MAIN CONTENT GRID */}
      <div className="flex-1 grid grid-cols-12 gap-3 min-h-0">

        {/* LEFT: CHART (8 Cols) */}
        <section className="col-span-12 lg:col-span-9 bg-[#0f0f0f] border border-zinc-800 rounded-xl relative flex flex-col overflow-hidden">

            {/* Chart Toolbar */}
            <div className="h-10 border-b border-zinc-800 bg-[#0a0a0a] flex items-center justify-between px-3 shrink-0">
                <div className="flex items-center gap-4">
                    <div className="flex gap-1">
                        {['15m', '1h', '4h', '1D'].map(t => (
                            <button key={t} className={`px-2 py-0.5 rounded text-[10px] font-bold ${t === '15m' ? 'bg-zinc-800 text-white' : 'text-zinc-500 hover:text-zinc-300'}`}>{t}</button>
                        ))}
                    </div>
                    <div className="w-px h-3 bg-zinc-800"></div>
                    <div className="flex gap-2 text-zinc-500">
                        <Crosshair size={14} className="hover:text-white cursor-pointer"/>
                        <PenTool size={14} className="hover:text-white cursor-pointer"/>
                        <Hash size={14} className="hover:text-white cursor-pointer"/>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1.5 px-2 py-1 bg-zinc-900 rounded border border-white/5">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                        <span className="text-[9px] font-bold text-zinc-400">Sync</span>
                    </div>
                    <Settings2 size={14} className="text-zinc-500 hover:text-white cursor-pointer"/>
                    <Maximize2 size={14} className="text-zinc-500 hover:text-white cursor-pointer"/>
                </div>
            </div>

            {/* CHART AREA */}
            <div className="flex-1 relative bg-[#050505] cursor-crosshair overflow-hidden">

                {/* --- DYNAMIC OVERLAYS --- */}
                <div className="absolute inset-0 z-20 pointer-events-none">

                    {/* LIQUIDATION LINE (Red Dashed) */}
                    <div 
                        className="absolute left-0 right-14 border-b border-rose-500/60 border-dashed flex items-end transition-all duration-300 ease-out group"
                        style={{ bottom: `${getY(liqPrice)}%` }}
                    >
                        <div className="absolute right-0 translate-x-full text-[9px] font-bold bg-rose-500 text-white px-1 py-0.5 rounded-r-sm">
                            {liqPrice.toFixed(2)}
                        </div>
                        <div className="absolute right-2 -top-5 text-[9px] font-bold text-rose-500 bg-rose-500/10 px-1.5 py-0.5 rounded flex items-center gap-1 opacity-80 group-hover:opacity-100 border border-rose-500/20 backdrop-blur-sm pointer-events-auto cursor-help">
                            <Skull size={10} /> Liq. Price
                            <span className="hidden group-hover:inline text-[8px] opacity-70 ml-1">(-1% Penalty)</span>
                        </div>
                    </div>

                    {/* ENTRY PRICE LINE (Blue Solid) */}
                    <div 
                        className="absolute left-0 right-14 border-b-2 border-blue-500/50 border-solid flex items-end transition-all duration-300"
                        style={{ bottom: `${getY(entryPrice)}%` }}
                    >
                        <div className="absolute right-0 translate-x-full text-[9px] font-bold bg-blue-600 text-white px-1 py-0.5 rounded-r-sm">
                            {entryPrice.toFixed(2)}
                        </div>
                        <div className="absolute left-4 -top-5 text-[9px] font-bold text-blue-400 bg-blue-500/10 px-1.5 py-0.5 rounded border border-blue-500/20 backdrop-blur-sm">
                            Entry (Exec)
                        </div>
                    </div>

                    {/* TAKE PROFIT LINE (Green Dashed) */}
                    {tpslEnabled && (
                        <div className="absolute left-0 right-14 border-b border-emerald-500/60 border-dashed transition-all duration-300 group" style={{ bottom: `${getY(tpPriceNum)}%` }}>
                            <div className="absolute right-0 translate-x-full text-[9px] font-bold bg-emerald-600 text-white px-1 py-0.5 rounded-r-sm">
                                {tpPriceNum.toFixed(2)}
                            </div>
                            <div className="absolute right-2 -top-5 text-[9px] font-bold text-emerald-500 bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20 backdrop-blur-sm flex items-center gap-1">
                                <TrendingUp size={10} /> Take Profit ({parseFloat(tpPercentInput).toFixed(2)}%)
                            </div>
                        </div>
                    )}

                    {/* STOP LOSS LINE (Orange Dashed) */}
                    {tpslEnabled && (
                        <div className="absolute left-0 right-14 border-b border-orange-500/60 border-dashed transition-all duration-300 group" style={{ bottom: `${getY(slPriceNum)}%` }}>
                            <div className="absolute right-0 translate-x-full text-[9px] font-bold bg-orange-600 text-white px-1 py-0.5 rounded-r-sm">
                                {slPriceNum.toFixed(2)}
                            </div>
                            <div className="absolute right-2 -top-5 text-[9px] font-bold text-orange-500 bg-orange-500/10 px-1.5 py-0.5 rounded border border-orange-500/20 backdrop-blur-sm flex items-center gap-1">
                                <AlertTriangle size={10} /> Stop Loss ({parseFloat(slPercentInput).toFixed(2)}%)
                            </div>
                        </div>
                    )}

                </div>

                {/* Candles Renderer */}
                <div className="absolute inset-0 flex items-end justify-between px-10 pb-8 z-10 gap-0.5 opacity-90">
                    {candles.map((c, i) => {
                        const isUp = c.close >= c.open;
                        const height = Math.abs(getY(c.close) - getY(c.open));
                        const wickHeight = Math.abs(getY(c.high) - getY(c.low));
                        const wickBottom = getY(c.low);
                        const bodyBottom = Math.min(getY(c.open), getY(c.close));

                        return (
                            <div key={i} className="flex-1 relative flex flex-col items-center h-full group hover:opacity-100 opacity-90 transition-opacity">
                                {/* Wick */}
                                <div 
                                    className={`w-[1px] absolute ${isUp ? 'bg-emerald-500' : 'bg-rose-500'}`} 
                                    style={{ height: `${wickHeight}%`, bottom: `${wickBottom}%` }}
                                ></div>
                                {/* Body */}
                                <div 
                                    className={`w-full absolute ${isUp ? 'bg-emerald-500' : 'bg-rose-500'}`} 
                                    style={{ 
                                        height: `${Math.max(height, 0.2)}%`, // Min height for doji
                                        bottom: `${bodyBottom}%` 
                                    }}
                                ></div>
                            </div>
                        );
                    })}
                </div>

                {/* Y-Axis Labels (Dynamic) */}
                <div className="absolute right-0 top-0 bottom-8 w-14 border-l border-zinc-800 bg-[#0a0a0a] flex flex-col justify-between py-4 z-30">
                    {[1, 0.75, 0.5, 0.25, 0].map(pct => {
                        const price = chartMax - ((chartMax - chartMin) * (1-pct)); 
                        return (
                            <div key={pct} className="text-[9px] font-mono text-zinc-600 text-right pr-2 relative h-0">
                                <span className="absolute -top-1.5 right-2">{price.toFixed(0)}</span>
                                <div className="absolute right-0 top-0 w-1 h-px bg-zinc-700"></div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </section>

        {/* RIGHT: ORDER TERMINAL */}
        <aside className="col-span-12 lg:col-span-3 bg-[#0f0f0f] border border-zinc-800 rounded-xl flex flex-col overflow-hidden">

            {/* TABS */}
            <div className="flex bg-[#0a0a0a] border-b border-zinc-800">
                <button onClick={() => setSide('long')} className={`flex-1 py-4 text-[11px] font-black uppercase tracking-widest transition-all relative ${side === 'long' ? 'text-emerald-500 bg-zinc-900' : 'text-zinc-500 hover:text-zinc-300'}`}>
                    Long / Buy
                    {side === 'long' && <div className="absolute top-0 left-0 right-0 h-0.5 bg-emerald-500"></div>}
                </button>
                <button onClick={() => setSide('short')} className={`flex-1 py-4 text-[11px] font-black uppercase tracking-widest transition-all relative ${side === 'short' ? 'text-rose-500 bg-zinc-900' : 'text-zinc-500 hover:text-zinc-300'}`}>
                    Short / Sell
                    {side === 'short' && <div className="absolute top-0 left-0 right-0 h-0.5 bg-rose-500"></div>}
                </button>
            </div>

            <div className="p-4 flex flex-col gap-5 overflow-y-auto scrollbar-hide flex-1">

                {/* ORDER TYPE */}
                <div className="flex items-center justify-between">
                    <div className="bg-black border border-white/5 rounded-lg p-0.5 flex">
                        <button onClick={() => setOrderType('market')} className={`px-3 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${orderType === 'market' ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}>Market</button>
                        <button onClick={() => setOrderType('limit')} className={`px-3 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${orderType === 'limit' ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}>Limit</button>
                    </div>
                    <div className="text-[10px] font-bold text-zinc-500 flex items-center gap-1 cursor-pointer hover:text-white transition-colors">
                        Isolated <ChevronDown size={10} />
                    </div>
                </div>

                {/* INPUTS */}
                <div className="space-y-3">
                    {orderType === 'limit' && (
                        <div className="bg-[#050505] border border-white/10 rounded-xl px-3 py-2.5 flex items-center justify-between group focus-within:border-white/20">
                            <div className="flex flex-col">
                                <label className="text-[9px] font-bold text-zinc-500 uppercase">Limit Price</label>
                                <input type="text" value={priceInput} onChange={(e) => setPriceInput(e.target.value)} placeholder={currentPrice.toFixed(2)} className="bg-transparent text-sm font-mono font-bold text-white outline-none w-24" />
                            </div>
                            <span className="text-[10px] font-bold text-zinc-500">USDT</span>
                        </div>
                    )}

                    <div className="bg-[#050505] border border-white/10 rounded-xl p-3 space-y-2 group focus-within:border-white/20">
                        <div className="flex justify-between items-center">
                            <label className="text-[9px] font-bold text-zinc-500 uppercase">Collateral</label>
                            <span className="text-[9px] font-mono text-zinc-500 flex items-center gap-1"><Wallet size={10} /> 42,500</span>
                        </div>
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 bg-zinc-900 px-2 py-1 rounded-lg border border-white/5">
                                <div className="w-4 h-4 rounded-full bg-emerald-500 flex items-center justify-center text-[8px] font-bold text-black">T</div>
                                <span className="text-xs font-bold text-white">USDT</span>
                            </div>
                            <input type="text" value={collateralInput} onChange={(e) => setCollateralInput(e.target.value)} placeholder="0.00" className="bg-transparent text-right text-lg font-mono font-bold text-white outline-none w-full" />
                        </div>
                    </div>
                </div>

                {/* LEVERAGE (1x-100x Safe, 100x-1000x Degen) */}
                <div className="bg-zinc-900/30 rounded-xl p-4 border border-white/5 space-y-4">
                    <div className="flex justify-between items-center">
                        <Minus size={14} className="text-zinc-500 cursor-pointer hover:text-white" onClick={() => setLeverage(Math.max(1, leverage - 1))} />
                        <span className="text-xl font-black font-mono text-white tracking-tight">{leverage}x</span>
                        <Plus size={14} className="text-zinc-500 cursor-pointer hover:text-white" onClick={() => setLeverage(Math.min(maxLeverage, leverage + 1))} />
                    </div>
                    <div className="relative h-6 w-full flex items-center">
                        <div className="absolute inset-x-0 h-1 bg-zinc-800 rounded-full overflow-hidden">
                            <div className={`h-full transition-all duration-150 ${leverage > 100 ? 'bg-gradient-to-r from-emerald-500 via-amber-500 to-rose-500' : 'bg-emerald-500'}`} style={{ width: `${(leverage / maxLeverage) * 100}%` }}></div>
                        </div>
                        <input type="range" min="1" max={maxLeverage} step="1" value={leverage} onChange={(e) => setLeverage(Number(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                        <div className="absolute w-4 h-4 bg-white rounded-full shadow-lg border-2 border-zinc-900 pointer-events-none transition-all duration-150" style={{ left: `calc(${(leverage / maxLeverage) * 100}% - 8px)` }}></div>
                    </div>
                    <div className="flex justify-between text-[9px] font-bold text-zinc-600 font-mono items-center">
                        <span>1x</span>
                        <span>{isDegenMode ? '500x' : '50x'}</span>
                        <span className={isDegenMode ? 'text-rose-500' : ''}>{maxLeverage}x</span>
                        <button onClick={toggleLock} className="ml-2 hover:text-white transition-colors" title={isDegenMode ? "Lock Leverage" : "Unlock High Leverage"}>
                            {isDegenMode ? <Unlock size={10} className="text-rose-500"/> : <Lock size={10}/>}
                        </button>
                    </div>
                </div>

                {/* TP / SL */}
                <div className="space-y-3">
                    <div className="flex items-center gap-2 cursor-pointer group" onClick={() => setTpslEnabled(!tpslEnabled)}>
                        <div className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${tpslEnabled ? 'bg-emerald-500 border-emerald-500' : 'bg-transparent border-zinc-700 group-hover:border-zinc-500'}`}>
                            {tpslEnabled && <Check size={10} className="text-black stroke-[4px]" />}
                        </div>
                        <label className="text-[10px] font-bold text-zinc-300 uppercase cursor-pointer group-hover:text-white">Take Profit / Stop Loss</label>
                    </div>

                    {tpslEnabled && (
                        <div className="space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                            {/* TP Row */}
                            <div className="grid grid-cols-2 gap-2">
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-emerald-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">TP Price</label>
                                    <input type="text" value={tpPriceInput} onChange={(e) => handleTpPriceChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-white w-full outline-none" />
                                </div>
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-emerald-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">Gain %</label>
                                    <input type="text" value={tpPercentInput} onChange={(e) => handleTpPercentChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-emerald-500 w-full outline-none" />
                                </div>
                            </div>
                            {/* SL Row */}
                            <div className="grid grid-cols-2 gap-2">
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-rose-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">SL Price</label>
                                    <input type="text" value={slPriceInput} onChange={(e) => handleSlPriceChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-white w-full outline-none" />
                                </div>
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-rose-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">Loss %</label>
                                    <input type="text" value={slPercentInput} onChange={(e) => handleSlPercentChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-rose-500 w-full outline-none" />
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* TRANSPARENCY RECEIPT - REDESIGNED */}
                <div className="mt-auto px-1 space-y-1">

                    {/* 1. SPREAD / EXECUTION PRICE */}
                    <div className="flex justify-between items-center group relative cursor-help py-2 border-b border-dashed border-white/5">
                        <span className="text-[10px] font-bold text-zinc-500 group-hover:text-zinc-300 transition-colors">Market vs Exec</span>
                        <div className="text-right">
                            <span className="text-xs font-mono font-bold text-white">${executionPrice.toLocaleString('en-US', {maximumFractionDigits: 2})}</span>
                            {spreadPct > 0 && <span className="text-[9px] text-zinc-600 block">Spread: {spreadPct}%</span>}
                        </div>
                        {/* Tooltip */}
                        <div className="absolute bottom-full left-0 mb-2 w-48 bg-zinc-900 border border-white/10 p-2 rounded text-[9px] text-zinc-300 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                            Includes 0.05% spread to cover volatility.
                        </div>
                    </div>

                    {/* 2. THE SILENT KILLER: FUNDING */}
                    <div className="flex justify-between items-center group relative cursor-help py-2 border-b border-dashed border-white/5">
                        <span className="text-[10px] font-bold text-zinc-500 group-hover:text-zinc-300 transition-colors flex items-center gap-1">
                            <Clock size={10} /> Funding Cost
                        </span>
                        <div className="text-right">
                            <span className={`text-xs font-mono font-bold ${isHighFunding ? 'text-amber-500' : 'text-zinc-400'}`}>
                                -${hourlyFundingCost.toFixed(2)} / hr
                            </span>
                            <span className="text-[9px] text-zinc-600 block">Next: {fundingTimer}</span>
                        </div>
                        {/* Tooltip */}
                        <div className="absolute bottom-full left-0 mb-2 w-48 bg-zinc-900 border border-white/10 p-2 rounded text-[9px] text-zinc-300 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                            Real-time cost to hold this position. Paid to shorts.
                        </div>
                    </div>

                    {/* 3. EXECUTION FEE (GAS) */}
                    <div className="flex justify-between items-center py-2 border-b border-dashed border-white/5">
                        <span className="text-[10px] font-bold text-zinc-500">Network Gas (Ext)</span>
                        <span className="text-xs font-mono font-bold text-blue-400">~${networkGas.toFixed(2)}</span>
                    </div>

                    {/* 4. LIQUIDATION PENALTY */}
                    <div className="flex justify-between items-center py-2 border-b border-dashed border-white/5">
                        <span className="text-[10px] font-bold text-zinc-500">Liq. Penalty</span>
                        <span className="text-xs font-mono font-bold text-rose-500">1.00%</span>
                    </div>

                    {/* 5. REVENUE SHARE (USER REBATE) */}
                    <div className="flex justify-between items-center pt-2">
                        <span className="text-[10px] font-bold text-purple-400 uppercase tracking-wide flex items-center gap-1">
                            <Zap size={10} fill="currentColor" /> Your Rebate
                        </span>
                        <span className="text-xs font-mono font-bold text-purple-400">+${userRebate.toFixed(4)}</span>
                    </div>

                </div>

                <button onClick={handleExecute} className={`w-full py-4 mt-2 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg transition-all active:scale-[0.98] ${themeBg} text-black hover:opacity-90`}>
                    {side === 'long' ? 'Open Long' : 'Open Short'}
                </button>

            </div>
        </aside>

      </div>
    </div>
  );
};

export default ProTradingView;
